CREATE TABLE public.profile_session_access (session_id uuid PRIMARY KEY, user_id uuid NOT NULL, credential_id uuid NOT NULL, restricted boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now(), password_failures integer NOT NULL DEFAULT 0, password_window_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profile_session_access TO authenticated;
GRANT ALL ON public.profile_session_access TO service_role;
ALTER TABLE public.profile_session_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own session scope" ON public.profile_session_access FOR SELECT TO authenticated USING (user_id=auth.uid() AND session_id::text=auth.jwt()->>'session_id');
CREATE FUNCTION public.customer_profile_restricted() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profile_session_access WHERE session_id::text=auth.jwt()->>'session_id' AND user_id=auth.uid() AND restricted) $$;
GRANT EXECUTE ON FUNCTION public.customer_profile_restricted() TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) AND NOT (_user_id=auth.uid() AND _role::text IN ('admin','management','staff','moderator','boro_fan_zone_moderator') AND public.customer_profile_restricted()) $$;
CREATE OR REPLACE FUNCTION public.has_any_role(_user_id uuid,_roles public.app_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=ANY(_roles) AND NOT (_user_id=auth.uid() AND role::text IN ('admin','management','staff','moderator','boro_fan_zone_moderator') AND public.customer_profile_restricted())) $$;
CREATE POLICY "restricted profile hides privileged roles" ON public.user_roles AS RESTRICTIVE FOR ALL TO authenticated USING (NOT public.customer_profile_restricted() OR role::text NOT IN ('admin','management','staff','moderator','boro_fan_zone_moderator')) WITH CHECK (NOT public.customer_profile_restricted());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['shifts','breaks','break_plan_times','shift_slots','shift_bookings','shift_swap_requests','away_log','holiday_requests','early_finish_requests','cover_requests','staff_records','staff_pin_requests','staff_pins','admin_backup_codes','admin_enabler_issues','admin_unlock_lockouts','admin_customer_account_switches','bank_transfer_details','bank_transfer_permissions','blacklist_entries','manual_name_customers','manual_customer_names','manually_added_customers','player_buffer_events','player_connection_log','player_connection_reports','app_download_log','notification_log','email_forwarding_confirmations','email_send_log','email_send_state','discord_import_queue','gate_applications'] LOOP IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public' AND tablename=t) THEN EXECUTE format('CREATE POLICY "customer profile denies staff data" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (NOT public.customer_profile_restricted()) WITH CHECK (NOT public.customer_profile_restricted())',t); END IF; END LOOP; END $$;
CREATE FUNCTION public.my_profile_access() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.profile_session_access; rs jsonb; staff boolean; BEGIN SELECT * INTO s FROM public.profile_session_access WHERE session_id::text=auth.jwt()->>'session_id' AND user_id=auth.uid(); SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text IN ('admin','management','staff','moderator')) INTO staff; SELECT COALESCE(jsonb_agg(role::text),'[]'::jsonb) INTO rs FROM public.user_roles WHERE user_id=auth.uid() AND (NOT COALESCE(s.restricted,false) OR role::text NOT IN ('admin','management','staff','moderator','boro_fan_zone_moderator')); IF COALESCE(s.restricted,false) AND staff THEN rs=rs || '["subscriber"]'::jsonb; END IF; RETURN jsonb_build_object('profileId',s.credential_id,'restricted',COALESCE(s.restricted,false),'canUseStaff',staff,'roles',rs); END $$;
GRANT EXECUTE ON FUNCTION public.my_profile_access() TO authenticated;
CREATE FUNCTION public.select_customer_profile(_credential uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$ DECLARE c private.app_credentials; sid uuid; restricted_now boolean; staff boolean; BEGIN sid=NULLIF(auth.jwt()->>'session_id','')::uuid; IF auth.uid() IS NULL OR sid IS NULL THEN RAISE EXCEPTION 'Verified session required'; END IF; SELECT * INTO c FROM private.app_credentials WHERE id=_credential AND owner_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Choose your own profile'; END IF; SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text IN ('admin','management','staff','moderator')) INTO staff; SELECT restricted INTO restricted_now FROM public.profile_session_access WHERE session_id=sid AND user_id=auth.uid(); IF staff AND c.account_number=1 AND COALESCE(restricted_now,false) THEN RAISE EXCEPTION 'Account password required to restore staff access'; END IF; INSERT INTO public.profile_session_access(session_id,user_id,credential_id,restricted) VALUES(sid,auth.uid(),c.id,staff AND c.account_number<>1) ON CONFLICT(session_id) DO UPDATE SET credential_id=excluded.credential_id,restricted=excluded.restricted,updated_at=now(); RETURN public.my_profile_access(); END $$;
GRANT EXECUTE ON FUNCTION public.select_customer_profile(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.select_customer_profile(uuid) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.my_profile_access() FROM PUBLIC,anon;